// ============================================================================
// TEST HARNESS HELPERS
// ============================================================================
struct TestResult {
    const char* name;
    int total_elements;
    int mismatches;
    int max_abs_error;
    bool passed;
};

void compare_tensors(
    const int8_t test_out[CONV1_OUT_CH][CONV1_OUT_H][CONV1_OUT_W],
    const int8_t* golden_flat,
    int total_elements,
    int& mismatches,
    int& max_abs_error
) {
    mismatches = 0;
    max_abs_error = 0;
    const int8_t* test_flat = reinterpret_cast<const int8_t*>(test_out);

    for (int i = 0; i < total_elements; ++i) {
        int diff = std::abs(static_cast<int>(test_flat[i]) - static_cast<int>(golden_flat[i]));
        if (diff > 0) {
            mismatches++;
            if (diff > max_abs_error) {
                max_abs_error = diff;
            }
        }
    }
}

// ============================================================================
// TEST SUITES
// ============================================================================

// Test 1: Real Image Inference
TestResult run_real_image_test() {
    const auto* in_tensor = reinterpret_cast<const int8_t(*)[CONV1_IN_H][CONV1_IN_W]>(GOLDEN_REAL_IN);
    int8_t out_tensor[CONV1_OUT_CH][CONV1_OUT_H][CONV1_OUT_W];

    conv1(in_tensor, out_tensor);

    TestResult res;
    res.name = "Real Test Image (346-split sample 0)";
    res.total_elements = CONV1_OUT_CH * CONV1_OUT_H * CONV1_OUT_W;
    compare_tensors(out_tensor, GOLDEN_REAL_OUT, res.total_elements, res.mismatches, res.max_abs_error);
    res.passed = (res.mismatches == 0 && res.max_abs_error == 0);
    return res;
}

// Test 2: All Zeros Boundary Test
TestResult run_zero_input_test() {
    int8_t zero_in[CONV1_IN_CH][CONV1_IN_H][CONV1_IN_W] = {0};
    int8_t out_tensor[CONV1_OUT_CH][CONV1_OUT_H][CONV1_OUT_W];

    conv1(zero_in, out_tensor);

    TestResult res;
    res.name = "Zero Input Boundary (Bias & ReLU test)";
    res.total_elements = CONV1_OUT_CH * CONV1_OUT_H * CONV1_OUT_W;
    compare_tensors(out_tensor, GOLDEN_ZERO_OUT, res.total_elements, res.mismatches, res.max_abs_error);
    res.passed = (res.mismatches == 0 && res.max_abs_error == 0);
    return res;
}

// Test 3: Positive Dynamic Range Test (+127 everywhere)
TestResult run_positive_saturation_test() {
    int8_t pos_in[CONV1_IN_CH][CONV1_IN_H][CONV1_IN_W];
    std::memset(pos_in, 127, sizeof(pos_in));
    int8_t out_tensor[CONV1_OUT_CH][CONV1_OUT_H][CONV1_OUT_W];

    conv1(pos_in, out_tensor);

    TestResult res;
    res.name = "Positive Range (+127 all elements)";
    res.total_elements = CONV1_OUT_CH * CONV1_OUT_H * CONV1_OUT_W;
    compare_tensors(out_tensor, GOLDEN_POS_OUT, res.total_elements, res.mismatches, res.max_abs_error);
    res.passed = (res.mismatches == 0 && res.max_abs_error == 0);
    return res;
}

// Test 4: Negative Input Test (-128 everywhere)
TestResult run_negative_relu_test() {
    int8_t neg_in[CONV1_IN_CH][CONV1_IN_H][CONV1_IN_W];
    std::memset(neg_in, -128, sizeof(neg_in));
    int8_t out_tensor[CONV1_OUT_CH][CONV1_OUT_H][CONV1_OUT_W];

    conv1(neg_in, out_tensor);

    TestResult res;
    res.name = "Negative Input (-128 all elements)";
    res.total_elements = CONV1_OUT_CH * CONV1_OUT_H * CONV1_OUT_W;
    compare_tensors(out_tensor, GOLDEN_NEG_OUT, res.total_elements, res.mismatches, res.max_abs_error);
    res.passed = (res.mismatches == 0 && res.max_abs_error == 0);
    return res;
}

// Test 5: Impulse Corner & Center Test
TestResult run_impulse_padding_test() {
    const auto* in_tensor = reinterpret_cast<const int8_t(*)[CONV1_IN_H][CONV1_IN_W]>(GOLDEN_IMP_IN);
    int8_t out_tensor[CONV1_OUT_CH][CONV1_OUT_H][CONV1_OUT_W];

    conv1(in_tensor, out_tensor);

    TestResult res;
    res.name = "Impulse (Padding border & center test)";
    res.total_elements = CONV1_OUT_CH * CONV1_OUT_H * CONV1_OUT_W;
    compare_tensors(out_tensor, GOLDEN_IMP_OUT, res.total_elements, res.mismatches, res.max_abs_error);
    res.passed = (res.mismatches == 0 && res.max_abs_error == 0);
    return res;
}

// Test 6: Scalar Requantization Boundary Tests
TestResult run_scalar_requant_tests() {
    TestResult res;
    res.name = "Scalar Requantization & Saturation Limits";
    res.total_elements = 6;
    res.mismatches = 0;
    res.max_abs_error = 0;

    // Test cases: (acc, M, S, expected)
    struct TestCase {
        int64_t acc;
        int64_t M;
        int S;
        int8_t expected;
    } cases[] = {
        {0, CONV1_M, CONV1_S, 0},                   // Zero accumulator -> 0
        {19140, CONV1_M, CONV1_S, 18},              // Max Conv1 bias (19140) -> 18
        {-2489, CONV1_M, CONV1_S, -2},             // Negative accumulator rounding -> -2
        {1000000000LL, CONV1_M, CONV1_S, 127},     // Large positive accumulator -> saturated to 127
        {-1000000000LL, CONV1_M, CONV1_S, -128},   // Large negative accumulator -> saturated to -128
        {16, 1, 4, 1}                              // (16 * 1 + 8) >> 4 = 24 >> 4 = 1
    };

    for (const auto& tc : cases) {
        int8_t actual = conv1_requantize(tc.acc, tc.M, tc.S);
        if (actual != tc.expected) {
            res.mismatches++;
            int diff = std::abs(static_cast<int>(actual) - static_cast<int>(tc.expected));
            if (diff > res.max_abs_error) res.max_abs_error = diff;
        }
    }

    res.passed = (res.mismatches == 0);
    return res;
}

// ============================================================================
// MAIN RUNNER
// ============================================================================
int main() {
    std::cout << "================================================================================\n";
    std::cout << "  Conv1 Layer C++ Verification Testbench\n";
    std::cout << "  Comparing Portable C++ Implementation vs Python Integer Reference\n";
    std::cout << "================================================================================\n\n";

    TestResult results[] = {
        run_real_image_test(),
        run_zero_input_test(),
        run_positive_saturation_test(),
        run_negative_relu_test(),
        run_impulse_padding_test(),
        run_scalar_requant_tests()
    };

    std::cout << std::left 
              << std::setw(42) << "Test Suite"
              << std::setw(14) << "Elements"
              << std::setw(14) << "Mismatches"
              << std::setw(12) << "Max Abs Err"
              << "Status\n";
    std::cout << "--------------------------------------------------------------------------------\n";

    bool all_passed = true;
    for (const auto& r : results) {
        std::cout << std::left 
                  << std::setw(42) << r.name
                  << std::setw(14) << r.total_elements
                  << std::setw(14) << r.mismatches
                  << std::setw(12) << r.max_abs_error
                  << (r.passed ? "[PASS]" : "[FAIL]") << "\n";
        if (!r.passed) {
            all_passed = false;
        }
    }

    std::cout << "================================================================================\n";
    if (all_passed) {
        std::cout << "  VERDICT: ALL 6 TEST SUITES PASSED (0 Mismatches across all tensors)\n";
        std::cout << "  Conv1 portable C++ implementation is BIT-EXACT with Python integer reference.\n";
    } else {
        std::cout << "  VERDICT: SOME TESTS FAILED. See mismatches above.\n";
    }
    std::cout << "================================================================================\n";

    return all_passed ? 0 : 1;
}
